addEventListener("keydown",e=>{if((e.key==="h"||e.key==="H")&&!e.metaKey&&!e.ctrlKey&&document.activeElement.tagName!=="SELECT"&&document.activeElement.tagName!=="INPUT")setHints(!showHints);});
